sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    if (api.state.selectedRecord == null || api.state.selectedRecord == undefined)
        return 100;
    if (api.state.recordCount == 1)
        return 27;
    if (api.state.recordCount == 2)
        return 29;
    if (api.state.recordCount == 3)
        return 31;
    if (api.state.recordCount == 4)
        return 33;
    else
        return 38;
}
